BEGIN TRANSACTION;
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
CREATE TABLE "artifacts" (
	id VARCHAR(36) NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	file_storage_key VARCHAR(512) NOT NULL, 
	mime_type VARCHAR(128) NOT NULL, 
	size_bytes INTEGER NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	lineage JSON, 
	origin VARCHAR(32) NOT NULL, 
	stage VARCHAR(64), 
	uploaded_by VARCHAR(36) NOT NULL, 
	uploaded_at DATETIME NOT NULL, 
	archived_at DATETIME, 
	archived_by VARCHAR(36), 
	purged_at DATETIME, 
	purged_by VARCHAR(36), 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	CONSTRAINT pk_artifacts PRIMARY KEY (id), 
	CONSTRAINT fk_artifacts_uploaded_by_users FOREIGN KEY(uploaded_by) REFERENCES users (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_artifacts_client_id FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT
);
CREATE TABLE "attack_assessments" (
	id VARCHAR(36) NOT NULL, 
	service_id VARCHAR(36) NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	version INTEGER DEFAULT '1' NOT NULL, 
	status VARCHAR(16) DEFAULT 'draft' NOT NULL, 
	approved_at DATETIME, 
	approved_by VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	documents_stale BOOLEAN DEFAULT 0 NOT NULL, catalog_version VARCHAR(16), 
	CONSTRAINT pk_attack_assessments PRIMARY KEY (id), 
	CONSTRAINT fk_attack_assessments_service_id_services FOREIGN KEY(service_id) REFERENCES services (id) ON DELETE CASCADE, 
	CONSTRAINT uq_attack_assessments_service_version UNIQUE (service_id, version), 
	CONSTRAINT fk_attack_assessments_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_attack_assessments_approved_by_users FOREIGN KEY(approved_by) REFERENCES users (id) ON DELETE SET NULL
);
CREATE TABLE "attack_coverage" (
	id VARCHAR(36) NOT NULL, 
	assessment_id VARCHAR(36) NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	technique_code VARCHAR(32) NOT NULL, 
	status VARCHAR(32), 
	notes TEXT, 
	evidence_artifact_id VARCHAR(36), 
	answered_by VARCHAR(36), 
	answered_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	locked BOOLEAN DEFAULT 0 NOT NULL, detection_tools JSON, prevention_tools JSON, response_tools JSON, rationale TEXT, unconfirmed_citations JSON, reason_code VARCHAR(48), narrative TEXT, 
	CONSTRAINT pk_attack_coverage PRIMARY KEY (id), 
	CONSTRAINT fk_attack_coverage_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_attack_coverage_evidence_artifact_id_artifacts FOREIGN KEY(evidence_artifact_id) REFERENCES artifacts (id) ON DELETE SET NULL, 
	CONSTRAINT fk_attack_coverage_assessment_id_attack_assessments FOREIGN KEY(assessment_id) REFERENCES attack_assessments (id) ON DELETE CASCADE, 
	CONSTRAINT fk_attack_coverage_answered_by_users FOREIGN KEY(answered_by) REFERENCES users (id) ON DELETE SET NULL, 
	CONSTRAINT uq_attack_coverage_assessment_technique UNIQUE (assessment_id, technique_code)
);
CREATE TABLE audit_entries (
	id VARCHAR(36) NOT NULL, 
	at DATETIME NOT NULL, 
	actor_user_id VARCHAR(36), 
	action VARCHAR(64) NOT NULL, 
	target_type VARCHAR(64) NOT NULL, 
	target_id VARCHAR(36), 
	details JSON, 
	correlation_id VARCHAR(128), 
	CONSTRAINT pk_audit_entries PRIMARY KEY (id), 
	CONSTRAINT fk_audit_entries_actor_user_id_users FOREIGN KEY(actor_user_id) REFERENCES users (id) ON DELETE SET NULL
);
CREATE TABLE "capability_items" (
	id VARCHAR(36) NOT NULL, 
	capability_list_id VARCHAR(36) NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	vendor VARCHAR(255), 
	category VARCHAR(128), 
	function VARCHAR(255), 
	annual_cost_usd NUMERIC(14, 2), 
	license_count INTEGER, 
	notes TEXT, 
	confidence_pct INTEGER, 
	source_artifact_id VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	disposition VARCHAR(16), 
	disposition_rationale TEXT, 
	consolidation_target_id VARCHAR(36), 
	locked BOOLEAN DEFAULT 0 NOT NULL, 
	parent_item_id CHAR(32), 
	security_related BOOLEAN, 
	security_functions JSON, 
	security_class_confirmed BOOLEAN DEFAULT 0 NOT NULL, 
	CONSTRAINT pk_capability_items PRIMARY KEY (id), 
	CONSTRAINT fk_capability_items_parent_item_id FOREIGN KEY(parent_item_id) REFERENCES capability_items (id) ON DELETE CASCADE, 
	CONSTRAINT fk_capability_items_consolidation_target_id FOREIGN KEY(consolidation_target_id) REFERENCES capability_items (id) ON DELETE SET NULL, 
	CONSTRAINT fk_capability_items_capability_list_id_capability_lists FOREIGN KEY(capability_list_id) REFERENCES capability_lists (id) ON DELETE CASCADE, 
	CONSTRAINT fk_capability_items_source_artifact_id_artifacts FOREIGN KEY(source_artifact_id) REFERENCES artifacts (id) ON DELETE SET NULL
);
CREATE TABLE capability_lists (
	id VARCHAR(36) NOT NULL, 
	service_id VARCHAR(36) NOT NULL, 
	version INTEGER DEFAULT '1' NOT NULL, 
	status VARCHAR(16) DEFAULT 'draft' NOT NULL, 
	approved_at DATETIME, 
	approved_by VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, source_rows_total INTEGER, excluded_rows JSON, approved_membership JSON, 
	CONSTRAINT pk_capability_lists PRIMARY KEY (id), 
	CONSTRAINT fk_capability_lists_service_id_services FOREIGN KEY(service_id) REFERENCES services (id) ON DELETE CASCADE, 
	CONSTRAINT fk_capability_lists_approved_by_users FOREIGN KEY(approved_by) REFERENCES users (id) ON DELETE SET NULL, 
	CONSTRAINT uq_capability_lists_service_id_version UNIQUE (service_id, version)
);
CREATE TABLE "client" (
	id VARCHAR(36) NOT NULL, 
	legal_name VARCHAR(255), 
	dba_name VARCHAR(255), 
	website VARCHAR(512), 
	size_band VARCHAR(64), 
	industry VARCHAR(128), 
	address_line1 VARCHAR(255), 
	address_line2 VARCHAR(255), 
	city VARCHAR(128), 
	state VARCHAR(64), 
	postal_code VARCHAR(32), 
	country VARCHAR(64), 
	primary_poc_user_id VARCHAR(36), 
	prompting_context TEXT, 
	service_interests JSON, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	intake_completed_at DATETIME, 
	archived_at DATETIME, 
	primary_contact_name VARCHAR(255), 
	primary_contact_email VARCHAR(320), 
	primary_contact_title VARCHAR(255), 
	primary_contact_phone VARCHAR(64), 
	CONSTRAINT pk_client PRIMARY KEY (id)
);
CREATE TABLE client_domain (
	id VARCHAR(36) NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	domain VARCHAR(255) NOT NULL, 
	created_by VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	CONSTRAINT pk_client_domain PRIMARY KEY (id), 
	CONSTRAINT fk_client_domain_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE CASCADE, 
	CONSTRAINT fk_client_domain_created_by_users FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL, 
	CONSTRAINT uq_client_domain_domain UNIQUE (domain)
);
CREATE TABLE "csf_answers" (
	id VARCHAR(36) NOT NULL, 
	assessment_id VARCHAR(36) NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	subcategory_code VARCHAR(16) NOT NULL, 
	maturity_tier SMALLINT, 
	notes TEXT, 
	evidence_artifact_id VARCHAR(36), 
	answered_by VARCHAR(36), 
	answered_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	locked BOOLEAN DEFAULT 0 NOT NULL, 
	CONSTRAINT pk_csf_answers PRIMARY KEY (id), 
	CONSTRAINT uq_csf_answers_assessment_subcategory UNIQUE (assessment_id, subcategory_code), 
	CONSTRAINT fk_csf_answers_assessment_id_csf_assessments FOREIGN KEY(assessment_id) REFERENCES csf_assessments (id) ON DELETE CASCADE, 
	CONSTRAINT fk_csf_answers_answered_by_users FOREIGN KEY(answered_by) REFERENCES users (id) ON DELETE SET NULL, 
	CONSTRAINT fk_csf_answers_evidence_artifact_id_artifacts FOREIGN KEY(evidence_artifact_id) REFERENCES artifacts (id) ON DELETE SET NULL, 
	CONSTRAINT fk_csf_answers_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT
);
CREATE TABLE "csf_assessments" (
	id VARCHAR(36) NOT NULL, 
	service_id VARCHAR(36) NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	version INTEGER DEFAULT '1' NOT NULL, 
	status VARCHAR(16) DEFAULT 'draft' NOT NULL, 
	approved_at DATETIME, 
	approved_by VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	documents_stale BOOLEAN DEFAULT 0 NOT NULL, 
	CONSTRAINT pk_csf_assessments PRIMARY KEY (id), 
	CONSTRAINT fk_csf_assessments_approved_by_users FOREIGN KEY(approved_by) REFERENCES users (id) ON DELETE SET NULL, 
	CONSTRAINT fk_csf_assessments_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT, 
	CONSTRAINT uq_csf_assessments_service_version UNIQUE (service_id, version), 
	CONSTRAINT fk_csf_assessments_service_id_services FOREIGN KEY(service_id) REFERENCES services (id) ON DELETE CASCADE
);
CREATE TABLE csf_dimension_scores (
	id VARCHAR(36) NOT NULL, 
	assessment_id VARCHAR(36) NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	tier VARCHAR(16) NOT NULL, 
	subcategory_code VARCHAR(16) NOT NULL, 
	governance SMALLINT DEFAULT '0' NOT NULL, 
	policy SMALLINT DEFAULT '0' NOT NULL, 
	implementation SMALLINT DEFAULT '0' NOT NULL, 
	monitoring SMALLINT DEFAULT '0' NOT NULL, 
	improvement SMALLINT DEFAULT '0' NOT NULL, 
	in_scope BOOLEAN DEFAULT 1 NOT NULL, 
	rationale TEXT, 
	what_we_found TEXT, 
	evidence_artifact_id VARCHAR(36), 
	has_evidence BOOLEAN DEFAULT 0 NOT NULL, 
	target_level SMALLINT, 
	locked BOOLEAN DEFAULT 0 NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, answer_source VARCHAR(16), 
	CONSTRAINT pk_csf_dimension_scores PRIMARY KEY (id), 
	CONSTRAINT fk_csf_dimension_scores_assessment_id_csf_assessments FOREIGN KEY(assessment_id) REFERENCES csf_assessments (id) ON DELETE CASCADE, 
	CONSTRAINT fk_csf_dimension_scores_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_csf_dimension_scores_evidence_artifact_id_artifacts FOREIGN KEY(evidence_artifact_id) REFERENCES artifacts (id) ON DELETE SET NULL, 
	CONSTRAINT uq_csf_dimension_scores_assessment_tier_subcat UNIQUE (assessment_id, tier, subcategory_code)
);
CREATE TABLE csf_gap_actions (
	id VARCHAR(36) NOT NULL, 
	assessment_id VARCHAR(36) NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	subcategory_code VARCHAR(16) NOT NULL, 
	characterization VARCHAR(16), 
	priority_override VARCHAR(2), 
	owner VARCHAR(255), 
	deadline VARCHAR(64), 
	resources TEXT, 
	success_criteria TEXT, 
	poam_ref VARCHAR(255), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	CONSTRAINT pk_csf_gap_actions PRIMARY KEY (id), 
	CONSTRAINT fk_csf_gap_actions_assessment_id_csf_assessments FOREIGN KEY(assessment_id) REFERENCES csf_assessments (id) ON DELETE CASCADE, 
	CONSTRAINT fk_csf_gap_actions_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT, 
	CONSTRAINT uq_csf_gap_actions_assessment_subcat UNIQUE (assessment_id, subcategory_code)
);
CREATE TABLE "deliverables" (
	id VARCHAR(36) NOT NULL, 
	service_id VARCHAR(36) NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	summary TEXT, 
	version INTEGER DEFAULT '1' NOT NULL, 
	pdf_artifact_id VARCHAR(36), 
	xlsx_artifact_id VARCHAR(36), 
	finalized_at DATETIME, 
	finalized_by VARCHAR(36), 
	superseded_by VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	docx_artifact_id VARCHAR(36), 
	released_at DATETIME, 
	released_by VARCHAR(36), parent_version INTEGER, frozen_target INTEGER, frozen_target_source VARCHAR(16), 
	CONSTRAINT pk_deliverables PRIMARY KEY (id), 
	CONSTRAINT fk_deliverables_service_id_services FOREIGN KEY(service_id) REFERENCES services (id) ON DELETE CASCADE, 
	CONSTRAINT fk_deliverables_superseded_by_deliverables FOREIGN KEY(superseded_by) REFERENCES deliverables (id) ON DELETE SET NULL, 
	CONSTRAINT fk_deliverables_pdf_artifact_id_artifacts FOREIGN KEY(pdf_artifact_id) REFERENCES artifacts (id) ON DELETE SET NULL, 
	CONSTRAINT fk_deliverables_finalized_by_users FOREIGN KEY(finalized_by) REFERENCES users (id) ON DELETE SET NULL, 
	CONSTRAINT fk_deliverables_xlsx_artifact_id_artifacts FOREIGN KEY(xlsx_artifact_id) REFERENCES artifacts (id) ON DELETE SET NULL, 
	CONSTRAINT fk_deliverables_released_by_users FOREIGN KEY(released_by) REFERENCES users (id) ON DELETE SET NULL
);
CREATE TABLE email_tokens (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	token_hash VARCHAR(128) NOT NULL, 
	purpose VARCHAR(32) NOT NULL, 
	expires_at DATETIME NOT NULL, 
	used_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	CONSTRAINT pk_email_tokens PRIMARY KEY (id), 
	CONSTRAINT fk_email_tokens_user FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE TABLE "llm_calls" (
	id VARCHAR(36) NOT NULL, 
	service_id VARCHAR(36), 
	purpose VARCHAR(64) NOT NULL, 
	prompt_version VARCHAR(32) NOT NULL, 
	provider VARCHAR(32) NOT NULL, 
	model VARCHAR(64) NOT NULL, 
	mode VARCHAR(16) NOT NULL, 
	input_tokens INTEGER, 
	output_tokens INTEGER, 
	duration_ms INTEGER, 
	status VARCHAR(16) NOT NULL, 
	error_message TEXT, 
	response_artifact_id VARCHAR(36), 
	requested_by VARCHAR(36) NOT NULL, 
	requested_at DATETIME NOT NULL, 
	completed_at DATETIME, 
	redacted_counts JSON, 
	correlation_id VARCHAR(128), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	client_id VARCHAR(36), redaction_mode VARCHAR(16), 
	CONSTRAINT pk_llm_calls PRIMARY KEY (id), 
	CONSTRAINT fk_llm_calls_requested_by_users FOREIGN KEY(requested_by) REFERENCES users (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_llm_calls_service_id FOREIGN KEY(service_id) REFERENCES services (id) ON DELETE SET NULL, 
	CONSTRAINT fk_llm_calls_response_artifact_id FOREIGN KEY(response_artifact_id) REFERENCES artifacts (id) ON DELETE SET NULL, 
	CONSTRAINT fk_llm_calls_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE SET NULL
);
CREATE TABLE llm_credential (
	id CHAR(32) NOT NULL, 
	provider VARCHAR(32) NOT NULL, 
	encrypted_key VARCHAR(2048) NOT NULL, 
	set_by_user_id CHAR(32), 
	last_validated_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	CONSTRAINT pk_llm_credential PRIMARY KEY (id), 
	CONSTRAINT uq_llm_credential_provider UNIQUE (provider)
);
CREATE TABLE messages (
	id VARCHAR(36) NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	service_id VARCHAR(36) NOT NULL, 
	author_user_id VARCHAR(36), 
	body TEXT NOT NULL, 
	read_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	CONSTRAINT pk_messages PRIMARY KEY (id), 
	CONSTRAINT fk_messages_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_messages_service_id_services FOREIGN KEY(service_id) REFERENCES services (id) ON DELETE CASCADE, 
	CONSTRAINT fk_messages_author_user_id_users FOREIGN KEY(author_user_id) REFERENCES users (id) ON DELETE SET NULL
);
CREATE TABLE notifications (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	event_type VARCHAR(64) NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	body TEXT, 
	link VARCHAR(512), 
	created_at DATETIME NOT NULL, 
	read_at DATETIME, 
	CONSTRAINT pk_notifications PRIMARY KEY (id), 
	CONSTRAINT fk_notifications_user_id_users FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE TABLE questions (
	id VARCHAR(36) NOT NULL, 
	framework_key VARCHAR(40) NOT NULL, 
	external_id VARCHAR(40) NOT NULL, 
	pillar VARCHAR(120) NOT NULL, 
	order_index INTEGER DEFAULT '0' NOT NULL, 
	stem TEXT NOT NULL, 
	cues JSON, 
	phase VARCHAR(40), 
	framework_activities JSON, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	CONSTRAINT pk_questions PRIMARY KEY (id), 
	CONSTRAINT uq_questions_framework_external_id UNIQUE (framework_key, external_id)
);
CREATE TABLE risk_entries (
	id VARCHAR(36) NOT NULL, 
	register_id VARCHAR(36) NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	title VARCHAR(512) NOT NULL, 
	description TEXT, 
	axis VARCHAR(16), 
	source VARCHAR(32), 
	source_id VARCHAR(64), 
	linked_techniques JSON, 
	linked_controls JSON, 
	likelihood VARCHAR(16), 
	impact VARCHAR(16), 
	tier VARCHAR(16), 
	compensating_controls TEXT, 
	residual_risk TEXT, 
	recommended_action VARCHAR(16), 
	rationale TEXT, 
	origin VARCHAR(24) DEFAULT 'ai_generated' NOT NULL, 
	trust VARCHAR(32), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, dropped_links JSON, 
	CONSTRAINT pk_risk_entries PRIMARY KEY (id), 
	CONSTRAINT fk_risk_entries_register_id_risk_registers FOREIGN KEY(register_id) REFERENCES risk_registers (id) ON DELETE CASCADE, 
	CONSTRAINT fk_risk_entries_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT
);
CREATE TABLE risk_registers (
	id VARCHAR(36) NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	version INTEGER DEFAULT '1' NOT NULL, 
	generated_by VARCHAR(36), 
	finalized_at DATETIME, 
	superseded_by VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, xlsx_artifact_id VARCHAR(36), pdf_artifact_id VARCHAR(36), docx_artifact_id VARCHAR(36), provenance JSON, 
	CONSTRAINT pk_risk_registers PRIMARY KEY (id), 
	CONSTRAINT fk_risk_registers_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE CASCADE, 
	CONSTRAINT fk_risk_registers_generated_by_users FOREIGN KEY(generated_by) REFERENCES users (id) ON DELETE SET NULL, 
	CONSTRAINT fk_risk_registers_superseded_by_risk_registers FOREIGN KEY(superseded_by) REFERENCES risk_registers (id) ON DELETE SET NULL
);
CREATE TABLE "service_requests" (
	id VARCHAR(36) NOT NULL, 
	service_type VARCHAR(32) NOT NULL, 
	requested_by VARCHAR(36) NOT NULL, 
	requested_at DATETIME NOT NULL, 
	notes TEXT, 
	deadline DATETIME, 
	fulfilled_service_id VARCHAR(36), 
	declined_at DATETIME, 
	declined_reason TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	csf_target_tier SMALLINT, 
	csf_profile VARCHAR(8), 
	zt_target_stage SMALLINT, 
	client_id VARCHAR(36) NOT NULL, 
	CONSTRAINT pk_service_requests PRIMARY KEY (id), 
	CONSTRAINT fk_service_requests_requested_by_users FOREIGN KEY(requested_by) REFERENCES users (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_service_requests_client_id FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT
);
CREATE TABLE "services" (
	id VARCHAR(36) NOT NULL, 
	kind VARCHAR(32) NOT NULL, 
	status VARCHAR(32) DEFAULT 'draft' NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	source_request_id VARCHAR(36), 
	opened_by VARCHAR(36) NOT NULL, 
	released_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	CONSTRAINT pk_services PRIMARY KEY (id), 
	CONSTRAINT fk_services_source_request_id_service_requests FOREIGN KEY(source_request_id) REFERENCES service_requests (id) ON DELETE SET NULL, 
	CONSTRAINT fk_services_opened_by_users FOREIGN KEY(opened_by) REFERENCES users (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_services_client_id FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT
);
CREATE TABLE user_recovery_codes (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	code_hash VARCHAR(512) NOT NULL, 
	used_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	CONSTRAINT pk_user_recovery_codes PRIMARY KEY (id), 
	CONSTRAINT fk_user_recovery_codes_user FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE TABLE "users" (
	id VARCHAR(36) NOT NULL, 
	email VARCHAR(320) NOT NULL, 
	password_hash VARCHAR(512) NOT NULL, 
	role VARCHAR(16) NOT NULL, 
	display_name VARCHAR(255), 
	title VARCHAR(255), 
	phone VARCHAR(64), 
	timezone VARCHAR(64) DEFAULT 'UTC' NOT NULL, 
	client_id VARCHAR(36), 
	is_active BOOLEAN DEFAULT 1 NOT NULL, 
	mfa_enrolled BOOLEAN DEFAULT 0 NOT NULL, 
	email_verified_at DATETIME, 
	last_login_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	failed_login_count INTEGER DEFAULT '0' NOT NULL, 
	last_failed_login_at DATETIME, 
	locked_until_at DATETIME, 
	active_refresh_jti VARCHAR(36), 
	mfa_totp_secret VARCHAR(512), 
	keycloak_sub VARCHAR(64), previous_refresh_jti VARCHAR(36), refresh_rotated_at DATETIME, 
	CONSTRAINT pk_users PRIMARY KEY (id), 
	CONSTRAINT fk_users_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT, 
	CONSTRAINT uq_users_email UNIQUE (email), 
	CONSTRAINT uq_users_keycloak_sub UNIQUE (keycloak_sub)
);
CREATE TABLE "zt_answers" (
	id VARCHAR(36) NOT NULL, 
	assessment_id VARCHAR(36) NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	capability_code VARCHAR(32) NOT NULL, 
	maturity_stage SMALLINT, 
	notes TEXT, 
	evidence_artifact_id VARCHAR(36), 
	answered_by VARCHAR(36), 
	answered_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	locked BOOLEAN DEFAULT 0 NOT NULL, target_stage SMALLINT, answer_source VARCHAR(16), 
	CONSTRAINT pk_zt_answers PRIMARY KEY (id), 
	CONSTRAINT fk_zt_answers_assessment_id_zt_assessments FOREIGN KEY(assessment_id) REFERENCES zt_assessments (id) ON DELETE CASCADE, 
	CONSTRAINT fk_zt_answers_evidence_artifact_id_artifacts FOREIGN KEY(evidence_artifact_id) REFERENCES artifacts (id) ON DELETE SET NULL, 
	CONSTRAINT fk_zt_answers_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT, 
	CONSTRAINT uq_zt_answers_assessment_capability UNIQUE (assessment_id, capability_code), 
	CONSTRAINT fk_zt_answers_answered_by_users FOREIGN KEY(answered_by) REFERENCES users (id) ON DELETE SET NULL
);
CREATE TABLE "zt_assessments" (
	id VARCHAR(36) NOT NULL, 
	service_id VARCHAR(36) NOT NULL, 
	client_id VARCHAR(36) NOT NULL, 
	framework VARCHAR(32) NOT NULL, 
	version INTEGER DEFAULT '1' NOT NULL, 
	status VARCHAR(16) DEFAULT 'draft' NOT NULL, 
	approved_at DATETIME, 
	approved_by VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	documents_stale BOOLEAN DEFAULT 0 NOT NULL, 
	CONSTRAINT pk_zt_assessments PRIMARY KEY (id), 
	CONSTRAINT fk_zt_assessments_service_id_services FOREIGN KEY(service_id) REFERENCES services (id) ON DELETE CASCADE, 
	CONSTRAINT uq_zt_assessments_service_version UNIQUE (service_id, version), 
	CONSTRAINT fk_zt_assessments_approved_by_users FOREIGN KEY(approved_by) REFERENCES users (id) ON DELETE SET NULL, 
	CONSTRAINT fk_zt_assessments_client_id_client FOREIGN KEY(client_id) REFERENCES client (id) ON DELETE RESTRICT
);
